parameters.text:
=Design a complete story bible and chapter-by-chapter outline for a novel.

WORKING TITLE: {{ $json.title }}
PREMISE: {{ $json.topic }}
CATEGORY: {{ $json.category }}
TARGET CHAPTER COUNT: {{ $json.chapter_count }}
TARGET AUDIENCE: {{ $json.audience }}

parameters.jsCode:
const cfg = $('⚙️ Prepare Context').first().json;
const raw = $input.first().json.output || '';
const match = raw.match(/```json\s*([\s\S]*?)```/i);
let chapters = [];
if (match) { try { chapters = JSON.parse(match[1]); } catch (e) { chapters = []; } }
if (!Array.isArray(chapters) || chapters.length === 0) {
  chapters = [{ chapter_number: 1, chapter_title: cfg.title, chapter_brief: cfg.topic }];
}
const storyBible = raw.split(/```json/i)[0].trim();

return chapters.map((c, i) => ({
  json: {
    title: cfg.title,
    category: cfg.category,
    audience: cfg.audience,
    author_voice: cfg.author_voice,
    is_fiction: true,
    chapter_number: c.chapter_number || (i + 1),
    chapter_title: c.chapter_title || `Chapter ${i + 1}`,
    chapter_brief: c.chapter_brief || '',
    story_context: storyBible,
    sources_block: ''
  }
}));

