parameters.jsCode:
const cfg = $('⚙️ Prepare Context').first().json;
const research = $('🔍 Research Agent').first().json.output || '';
let sources = '';
const srcSplit = research.split(/###\s*SOURCES/i);
if (srcSplit.length > 1) sources = srcSplit[1].trim();
const researchSummary = srcSplit[0].trim();

const raw = $input.first().json.output || '';
const match = raw.match(/```json\s*([\s\S]*?)```/i);
let chapters = [];
if (match) { try { chapters = JSON.parse(match[1]); } catch (e) { chapters = []; } }
if (!Array.isArray(chapters) || chapters.length === 0) {
  chapters = [{ chapter_number: 1, chapter_title: cfg.title, chapter_brief: cfg.topic }];
}

return chapters.map((c, i) => ({
  json: {
    title: cfg.title,
    category: cfg.category,
    audience: cfg.audience,
    author_voice: cfg.author_voice,
    is_fiction: false,
    chapter_number: c.chapter_number || (i + 1),
    chapter_title: c.chapter_title || `Chapter ${i + 1}`,
    chapter_brief: c.chapter_brief || '',
    story_context: researchSummary,
    sources_block: sources
  }
}));

return $input.all().map(item => ({
  json: {
    title: item.json.title,
    category: item.json.category || '',
    audience: item.json.audience,
    author_voice: item.json.author_voice,
    is_fiction: !!item.json.is_fiction,
    chapter_number: item.json.chapter_number,
    chapter_title: item.json.chapter_title,
    chapter_brief: item.json.chapter_brief,
    story_context: item.json.story_context || '',
    sources_block: item.json.sources_block || ''
  }
}));

parameters.text:
=Write full Chapter {{ $json.chapter_number }}: {{ $json.chapter_title }} of "{{ $json.title }}".

CHAPTER BRIEF:
{{ $json.chapter_brief }}

BACKGROUND CONTEXT (story bible for fiction, research summary for nonfiction):
{{ $json.story_context }}

AUDIENCE: {{ $json.audience }}
CATEGORY: {{ $json.category }}

parameters.jsCode:
const cfg = $('⚙️ Prepare Context').first().json;
const humanizedItems = $input.all();
const outlineItems = $('🧩 Normalize Chapters').all();

const chapters = humanizedItems.map((item, i) => {
  const o = outlineItems[i] ? outlineItems[i].json : {};
  return {
    number: o.chapter_number ?? (i + 1),
    title: o.chapter_title ?? `Chapter ${i + 1}`,
    content: (item.json.output || '').trim(),
    sources_block: o.sources_block || ''
  };
}).sort((a, b) => a.number - b.number);

const isFiction = !!(outlineItems[0] && outlineItems[0].json.is_fiction);

const toc = chapters.map(c => `- Chapter ${c.number}: ${c.title}`).join('\n');
const body = chapters.map(c => `## Chapter ${c.number}: ${c.title}\n\n${c.content}`).join('\n\n---\n\n');

let allSources = '_No structured sources returned — verify claims manually._';
if (!isFiction && outlineItems[0] && outlineItems[0].json.sources_block) {
  allSources = outlineItems[0].json.sources_block;
}

const date = new Date().toISOString().slice(0, 10);
const genreLine = (isFiction ? 'Fiction' : 'Nonfiction') + (cfg.category ? ' · ' + cfg.category : '');

let finalMarkdown = `# ${cfg.title}\n\n*${genreLine} · For: ${cfg.audience}*\n*Generated: ${date}*\n\n---\n\n## Table of Contents\n\n${toc}\n\n---\n\n${body}\n`;

if (!isFiction) {
  finalMarkdown += `\n---\n\n## Sources & References\n\n${allSources}\n`;
} else {
  finalMarkdown += `\n---\n\n*This is a work of fiction. Any resemblance to real events or persons is coincidental.*\n`;
}

return [{
  json: {
    title: cfg.title,
    is_fiction: isFiction,
    chapter_count: chapters.length,
    generated_date: date,
    final_markdown: finalMarkdown
  }
}];
